require_once dirname(__DIR__) . '/app/auth-capabilities.php';
require_once dirname(__DIR__) . '/app/data-slot.php';
require_once dirname(__DIR__) . '/app/leden/service.php';
require_once dirname(__DIR__) . '/evenementen-opslag.php';
if(!$ingelogd){header('Location: ./');exit;}
if(!authHeeftCapability('events.manage')){http_response_code(403);echo'Geen toegang tot Evenementen.';exit;}
function evEsc($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function evFlash(string $t,string $type='ok'):void{$_SESSION['events_flash']=['tekst'=>$t,'type'=>$type];}
function evRedirect():void{header('Location: evenementen.php');exit;}
function evVind(array $data,string $id):?int{foreach($data['evenementen'] as $i=>$e)if(is_array($e)&&($e['id']??'')===$id)return$i;return null;}
$flash=$_SESSION['events_flash']??null;unset($_SESSION['events_flash']);
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 if(!csrfOk()){evFlash('Sessie verlopen.','fout');evRedirect();}$slot=dataSlotOpen();try{$data=evenementenLees();$actie=(string)($_POST['actie']??'');
  if($actie==='opslaan'){$id=trim((string)($_POST['id']??''));$idx=$id===''?null:evVind($data,$id);$bestaand=$idx===null?null:$data['evenementen'][$idx];$datum=ledenParseDatum($_POST['datum']??'');$begin=ledenParseDatum($_POST['inschrijving_begin']??'');$eind=ledenParseDatum($_POST['inschrijving_eind']??'');if($begin!==''&&$eind!==''&&$eind<$begin){evFlash('Einddatum inschrijving kan niet vóór de begindatum liggen.','fout');}else{$e=evenementNormaliseer(['titel'=>$_POST['titel']??'','locatie'=>$_POST['locatie']??'','betaalverzoek'=>$_POST['betaalverzoek']??'','omschrijving'=>$_POST['omschrijving']??'','datum'=>$datum,'tijd'=>$_POST['tijd']??'','eindtijd'=>$_POST['eindtijd']??'','inschrijving_begin'=>$begin,'inschrijving_eind'=>$eind,'capaciteit'=>$_POST['capaciteit']??'','zichtbaarheid'=>$_POST['zichtbaarheid']??'leden','deelnemers'=>$_POST['deelnemers']??[]],$bestaand);$geldige=array_column(ledenServiceLees()['leden'],'id');$e['deelnemers']=array_values(array_intersect($e['deelnemers'],$geldige));if($idx===null){$e['nummer']=evenementVolgendNummer($data);$e['aangemaakt_door']=$huidigeGebruiker;$data['evenementen'][]=$e;}else$data['evenementen'][$idx]=$e;if(evenementenSchrijf($data)){schrijfLog($logBestand,$huidigeGebruiker,'evenement_opgeslagen',$e['id'].' · '.$e['titel']);evFlash('Evenement opgeslagen.');}else evFlash('Opslaan mislukt.','fout');}}
  elseif($actie==='verwijderen'){$id=trim((string)($_POST['id']??''));$idx=evVind($data,$id);if($idx===null)evFlash('Evenement niet gevonden.','fout');else{$e=$data['evenementen'][$idx];array_splice($data['evenementen'],$idx,1);if(evenementenSchrijf($data)){schrijfLog($logBestand,$huidigeGebruiker,'evenement_verwijderd',$id.' · '.evenementWeergavenaam($e));evFlash('Evenement verwijderd.');}else evFlash('Verwijderen mislukt.','fout');}}
 }finally{dataSlotDicht($slot);}evRedirect();
}
$data=evenementenLees();$lijst=evenementenGesorteerd($data);$editId=trim((string)($_GET['edit']??''));$edit=null;if($editId!=='')foreach($data['evenementen'] as $e)if(is_array($e)&&($e['id']??'')===$editId){$edit=$e;break;}$toon=($_GET['nieuw']??'')==='1'||$edit!==null;$e=$edit??['zichtbaarheid'=>'leden','deelnemers'=>[]];$leden=array_values(array_filter(ledenServiceLees()['leden'],static fn($l)=>is_array($l)&&empty($l['gearchiveerd_op'])));usort($leden,static fn($a,$b)=>strcmp(ledenSorteernaam($a),ledenSorteernaam($b)));
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Evenementen</title><style>body{margin:0;background:#f6f2e8;color:#26351d;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.top{padding:14px 22px;background:#fff;border-bottom:1px solid #ddd8c0}.top a{color:#2d6260;font-weight:750;text-decoration:none}.wrap{max-width:1100px;margin:30px auto;padding:0 20px 70px}.card{background:#fff;border:1px solid #ddd8c0;border-radius:14px;padding:20px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.veld label{display:block;font-weight:700;margin-bottom:5px}.veld input,.veld select,.veld textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #d3ccb7;border-radius:8px;font:inherit}.veld textarea{min-height:110px}.leden{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.btn{display:inline-block;border:1px solid #d3ccb7;background:#fff;color:#2d6260;border-radius:8px;padding:9px 12px;text-decoration:none;font:inherit;font-weight:750;cursor:pointer}.btn.primary{background:#3a7a77;color:#fff;border:0}.btn.danger{background:#fff0ed;color:#8b2e27}.actions{display:flex;gap:8px;flex-wrap:wrap}.item{border-top:1px solid #eee9db;padding:12px 0}.meta{font-size:13px;color:#68705f}.melding{padding:12px;border-radius:8px;background:#eaf6ee}.melding.fout{background:#fdeceb;color:#8b2e27}@media(max-width:800px){.grid,.leden{grid-template-columns:1fr}}</style></head><body><div class="top"><a href="./">← Beheer</a></div><main class="wrap"><h1>Evenementen</h1><a class="btn primary" href="?nieuw=1">+ Evenement</a><?php if($flash):?><div class="melding <?=evEsc($flash['type']??'')?>"><?=evEsc($flash['tekst']??'')?></div><?php endif;?><?php if($toon):?><section class="card"><h2><?=$edit?'Evenement bewerken':'Nieuw evenement'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=evEsc($csrfToken)?>"><input type="hidden" name="actie" value="opslaan"><input type="hidden" name="id" value="<?=evEsc($edit['id']??'')?>"><div class="grid"><div class="veld"><label>Titel</label><input name="titel" maxlength="160" value="<?=evEsc($e['titel']??'')?>"></div><div class="veld"><label>Datum</label><input type="date" name="datum" value="<?=evEsc($e['datum']??'')?>"></div><div class="veld"><label>Locatie</label><input name="locatie" maxlength="120" value="<?=evEsc($e['locatie']??'')?>"></div><div class="veld"><label>Starttijd</label><input name="tijd" value="<?=evEsc($e['tijd']??'')?>"></div><div class="veld"><label>Eindtijd</label><input name="eindtijd" value="<?=evEsc($e['eindtijd']??'')?>"></div><div class="veld"><label>Capaciteit (0 = onbeperkt)</label><input type="number" min="0" max="9999" name="capaciteit" value="<?=evEsc($e['capaciteit']??0)?>"></div><div class="veld"><label>Zichtbaarheid</label><select name="zichtbaarheid"><?php foreach(evenementZichtbaarheden() as $k=>$lab):?><option value="<?=evEsc($k)?>" <?=($e['zichtbaarheid']??'')===$k?'selected':''?>><?=evEsc($lab)?></option><?php endforeach;?></select></div><div class="veld"><label>Inschrijving vanaf</label><input type="date" name="inschrijving_begin" value="<?=evEsc($e['inschrijving_begin']??'')?>"></div><div class="veld"><label>Inschrijving t/m</label><input type="date" name="inschrijving_eind" value="<?=evEsc($e['inschrijving_eind']??'')?>"></div></div><div class="veld"><label>Omschrijving</label><textarea name="omschrijving"><?=evEsc($e['omschrijving']??'')?></textarea></div><div class="veld"><label>Betaalverzoek / instructie</label><input name="betaalverzoek" maxlength="500" value="<?=evEsc($e['betaalverzoek']??'')?>"></div><h3>Deelnemers</h3><div class="leden"><?php foreach($leden as $l):?><label><input type="checkbox" name="deelnemers[]" value="<?=evEsc($l['id'])?>" <?=in_array($l['id'],(array)($e['deelnemers']??[]),true)?'checked':''?>> <?=evEsc(ledenVolledigeNaam($l))?></label><?php endforeach;?></div><div class="actions" style="margin-top:14px"><button class="btn primary" type="submit">Opslaan</button><a class="btn" href="evenementen.php">Annuleren</a></div></form></section><?php endif;?><section class="card"><h2>Overzicht</h2><?php foreach($lijst as $item):?><div class="item"><strong><?=evEsc(evenementWeergavenaam($item))?></strong><br><span class="meta"><?=evEsc($item['datum']??'')?> · <?=evEsc(evenementStatus($item))?> · <?=evEsc(evenementAantalDeelnemers($item))?> deelnemer(s)<?=evenementIsVol($item)?' · VOL':''?></span><div class="actions"><a class="btn" href="?edit=<?=evEsc($item['id'])?>">Bewerken</a><form method="post" onsubmit="return confirm('Evenement verwijderen?');"><input type="hidden" name="csrf" value="<?=evEsc($csrfToken)?>"><input type="hidden" name="actie" value="verwijderen"><input type="hidden" name="id" value="<?=evEsc($item['id'])?>"><button class="btn danger" type="submit">Verwijderen</button></form></div></div><?php endforeach;?></section></main></body></html>
